export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

// Each widget awaits this independently so no single component has to know about
// the others' data. `cache` memoizes the call for the lifetime of one request, so
// the three awaits below still add up to a single fetch per render.
export const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
})

