import { Suspense } from 'react'
import { RevenueChart, RevenueChartSkeleton } from './RevenueChart'
import { LatestInvoices, LatestInvoicesSkeleton } from './LatestInvoices'
import { CardStats, CardStatsSkeleton } from './CardStats'

// Intentionally not `async`: nothing in this component touches request-time data,
// so the whole layout below — headings included — is prerendered into the static
// shell, and each widget streams into its own boundary when its data lands.
export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChart />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoices />
      </Suspense>
    </main>
  )
}

